{
  "segment_function": "Define the durability of the world, distinguishing work (homo faber) from labor (animal laborans) and use from consumption.",
  "claims": [
    {
      "claim": "The work of our hands creates the human artifice out of things whose proper use does not cause them to disappear, granting the human artifice stability and solidity.",
      "claim_type": "author_position",
      "supporting_excerpt": "The work of our hands, as distinguished from the labor of our bodies— homo faber who makes and literally “works upon” as distinguished from the animal laborans which labors and “mixes with”—fabricates the sheer unending variety of things whose sum total constitutes the human artifice. They are mostly, but not exclusively, objects for use and they possess the durability Locke needed for the establishment of property, the “value” Adam Smith needed for the exchange market, and they bear testimony to productivity, which Marx believed to be the test of human nature. Their proper use does not cause them to disappear and they give the human artifice the stability and solidity without which it could not be relied upon to house the unstable and mortal creature which is man.",
      "support_kind": "direct",
      "qualifications": [
        "things are mostly, but not exclusively, objects for use"
      ],
      "confidence": 1.0
    },
    {
      "claim": "Durability gives the things of the world their relative independence and objectivity, which serves to stabilize human life and allow men to retrieve their identity.",
      "claim_type": "author_position",
      "supporting_excerpt": "It is this durability which gives the things of the world their relative independence from men who produced and use them, their “objectivity” which makes them withstand, “stand against” and endure, at least for a time, the voracious needs and wants of their living makers and users. From this viewpoint, the things of the world have the function of stabilizing human life, and their objectivity lies in the fact that—in contradiction to the Heraclitean saying that the same man can never enter the same stream—men, their ever-changing nature notwithstanding, can retrieve their sameness, that is, their identity, by being related to the same chair and the same table.",
      "support_kind": "direct",
      "qualifications": [
        "endure, at least for a time"
      ],
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "Homo faber",
      "definition": "The maker who literally works upon materials to fabricate the unending variety of things that constitute the human artifice."
    },
    {
      "term": "Animal laborans",
      "definition": "The laborer who labors and mixes with materials in connection with the biological life process."
    }
  ],
  "distinctions": [
    {
      "item_a": "Work",
      "item_b": "Labor",
      "distinction": "Work involves making and working upon materials as homo faber to create durable objects constituting the human artifice, whereas labor involves the body mixing with things as animal laborans."
    },
    {
      "item_a": "Use",
      "item_b": "Consumption",
      "distinction": "Destruction is incidental to use and wears down durability, whereas destruction is the inherent end of all things for consumption."
    }
  ],
  "examples": [],
  "objections": [],
  "responses": [],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The distinction between homo faber (work) and animal laborans (labor).",
    "The role of durability and objectivity in stabilizing human life and identity against natural biological cycles."
  ]
}

